Question 1 : Explain the functionality of the following functions.
            C++

    using namespace std;
int fun1(int x, int y)
{
    if (x == 0)
        return y;
    else
        return fun1(x - 1, x + y);
}

int main()
{
    cout << fun1(5, 2) << endl;  
    return 0;
}


            C

    int fun1(int x, int y)
{
    if (x == 0)
        return y;
    else
        return fun1(x - 1, x + y);
}

// Driver code
int main()
{
    printf("%d\n", fun1(5, 2));   
    return 0;
}


            Java

    static int fun1(int x, int y)
{
    if (x == 0)
        return y;
    else
        return fun1(x - 1, x + y);
}

// Driver code
public static void main(String[] args)
{
    System.out.println(fun1(5, 2)); 
}


            Python

    def fun1(x, y) :

    if (x == 0) :
        return y
    else :
        return fun1(x - 1, x + y)

# Driver code
print(fun1(5, 2)) 


            C#

    using System;

class GFG {

    static int fun1(int x, int y)
    {
        if (x == 0)
            return y;
        else
            return fun1(x - 1, x + y);
    }

    // Driver code
    static void Main(string[] args)
    {
        Console.WriteLine(fun1(5, 2));  
    }
}


            JavaScript

    function fun1(x, y)
{
    if (x == 0) 
        return y
    else 
        return fun1(x - 1, x + y)
}

// Driver code

console.log(fun1(5, 2)); 

Answer: This function adds the sum of first x natural numbers to y. It repeatedly decreases x and adds its value to y until x becomes 0. Final result: y + (1 + 2 + ... + x) = y + x(x + 1) / 2. For example, if x is 5 and y is 2, then fun should return 15 + 2 = 17.Question 2 : Explain the functionality of the following functions.
            C++

    using namespace std;

/* Assume that n is greater than or equal to 1 */
int fun1(int n)
{
    if (n == 1)
        return 0;
    else
        return 1 + fun1(n / 2);
}

// Driver code
int main() {

    cout << fun1(8);
    return 0;
}


