            JavaScript

    // Assume that n is greater than or equal to 1
function fun1(n)
{
    if (n <= 1)
        return 0
    else
        return 1 + fun1(Math.floor(n / 2))
}

// Driver code
console.log(fun1(8))

The above function calculates and returns ⌊log2(n)⌋. For example, if n is between 8 and 15 then fun1() returns 3. If n is between 16 to 31 then fun1() returns 4.Question 3
            C++

    using namespace std;

/* Assume that n is greater than or equal to 0 */
void fun2(int n)
{
    if (n == 0)
        return;

    fun2(n / 2);
    cout << n % 2;
}

// Driver code

int main()
{
    fun2(21);
    return 0;
}


            C

    #include <stdio.h>

void fun2(int n)
{
  if(n == 0)
    return;

  fun2(n/2);
  printf("%d", n%2);
}

// Driver code

int main() {

    fun2(21);
    return 0;
}


            Java

    class GFG {

    /* Assume that n is greater than or equal to 1 */
    static void fun2(int n)
    {
        if (n == 0)
            return;

        fun2(n / 2);
        System.out.print(n % 2);
    }

    // Driver code

    public static void main(String[] args) { fun2(21); }
}


            Python

    def fun2(n):
    if(n == 0):
        return

    fun2(n // 2)
    print(n % 2, end="")

# Driver code

fun2(21)


            C#

    using System;

public class GFG {

    static void fun2(int n)
    {
        if (n == 0)
            return;

        fun2(n / 2);
        Console.Write(n % 2);
    }
    // Driver code
    static public void Main()
    {
        fun2(21);
    }
}


            JavaScript

    // Assume that n is greater than or equal to 1 
function fun2(n)
{
    if (n == 0)
        return;

    fun2(Math.floor(n / 2));
    console.log(n % 2 + " ")
}

// Driver code
fun2(21)

Answer: The function fun2() prints the binary equivalent of n. For example, if n is 21 then fun2() prints 10101. Question 4 : Predict the output of the following program. 
            C++

    #include <iostream>
using namespace std;

void fun(int x) 
{ 
    if(x > 0) 
    { 
        fun(--x); 
        cout << x <<" "; 
        fun(--x); 
    } 
} 

// Driver code
int main() 
{ 
    int a = 4; 
    fun(a); 
    return 0; 
} 


            C

    #include<stdio.h>
void fun(int x)
{
  if(x > 0)
  {
     fun(--x);
     printf("%d\t", x);
     fun(--x);
  }
}

// Driver code
int main()
{
  int a = 4;
  fun(a);
  getchar();
  return 0;
}


