            C++

    using namespace std;
void fun1(int n) 
{ 
   int i = 0;   
   if (n > 1) 
     fun1(n - 1); 
   for (i = 0; i < n; i++) 
     cout << " * "; 
} 

// Driver code
int main()
{
    fun1(4);
}


            C

    void fun1(int n)
{
   int i = 0;  
   if (n > 1)
     fun1(n-1);
   for (i = 0; i < n; i++)
     printf(" * ");
}

// Driver code
void main()
{
    fun1(4);
}


            Java

    class GFG {

    static void fun1(int n)
    {
        int i = 0;
        if (n > 1)
            fun1(n - 1);
        for (i = 0; i < n; i++)
            System.out.print(" * ");
    }

    // Driver code
    public static void main(String[] args) { fun1(4); }
}


            Python

    def fun1(n):
    i = 0
    if (n > 1):
        fun1(n - 1)
    for i in range(n):
        print(" * ", end="")

# Driver code
fun1(4)


            C#

    using System;
class GFG {
    static void fun1(int n)
    {
        int i = 0;
        if (n > 1)
            fun1(n - 1);
        for (i = 0; i < n; i++)
            Console.Write(" * ");
    }

    // Driver code
    static void Main(string[] args) { fun1(4); }
}


            JavaScript

    function fun1(n)
{
    let i = 0;

    if (n > 1)
        fun1(n - 1);

    for (i = 0; i < n; i++)
        console.log(" * ");
}

// Driver code
fun1(4)

Answer: Total numbers of stars printed is equal to 1 + 2 + .... (n-2) + (n-1) + n, which is n(n+1)/2. Please write comments if you find any of the answers/codes incorrect, or you want to share more information about the topics discussed above.
